import{_ as s,c as o,o as a,j as i,Y as r,t as n}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"git-http-push | x-cmd man (git man1) | Push objects over HTTP/DAV to another repository","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-http-push - Push objects over HTTP/DAV to another repository","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-http-push | x-cmd man (git man1) | Push objects over HTTP/DAV to another repository"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-http-push - Push objects over HTTP/DAV to another repository"}]]},"headers":[],"params":{"isMan":true,"man":"git-http-push","category":"git man1","desc":"Push objects over HTTP/DAV to another repository"},"relativePath":"git/man1/git-http-push.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-http-push.md"},l={class:"visually-hidden"};function p(e,t,c,d,m,u){return a(),o("div",null,[i("h1",l,n(e.$params.man),1),t[0]||(t[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-http-push - Push objects over HTTP/DAV to another repository</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http-push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--all] [--dry-run] [--force] [--verbose] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ref</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ref</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Sends missing objects to remote repository, and updates the remote branch.</p><p><strong>NOTE</strong>: This command is temporarily disabled if your libcurl is older than 7.16, as the combination has been reported not to work and sometimes corrupts repository.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--all</p><blockquote><p>Do not assume that the remote repository is complete in its current state, and verify all objects in the entire local ref&#39;s history exist in the remote repository.</p></blockquote><p>--force</p><blockquote><p>Usually, the command refuses to update a remote ref that is not an ancestor of the local ref used to overwrite it. This flag disables the check. What this means is that the remote repository can lose commits; use it with care.</p></blockquote><p>--dry-run</p><blockquote><p>Do everything except actually send the updates.</p></blockquote><p>--verbose</p><blockquote><p>Report the list of objects being walked locally and the list of objects successfully sent to the remote repository.</p></blockquote><p>-d, -D</p><blockquote><p>Remove &lt;ref&gt; from remote repository. The specified branch cannot be the remote HEAD. If -d is specified the following other conditions must also be met:</p><blockquote><p>·</p><p>Remote HEAD must resolve to an object that exists locally</p></blockquote><blockquote><p>·</p><p>Specified branch resolves to an object that exists locally</p></blockquote><blockquote><p>·</p><p>Specified branch is an ancestor of the remote HEAD</p></blockquote></blockquote><p>&lt;ref&gt;...</p><blockquote><p>The remote refs to update.</p></blockquote><h2 id="specifying-the-refs" tabindex="-1">SPECIFYING THE REFS <a class="header-anchor" href="#specifying-the-refs" aria-label="Permalink to &quot;SPECIFYING THE REFS&quot;">​</a></h2><p>A <em>&lt;ref&gt;</em> specification can be either a single pattern, or a pair of such patterns separated by a colon &quot;:&quot; (this means that a ref name cannot have a colon in it). A single pattern <em>&lt;name&gt;</em> is just a shorthand for <em>&lt;name&gt;:&lt;name&gt;</em>.</p><p>Each pattern pair <em>&lt;src&gt;:&lt;dst&gt;</em> consists of the source side (before the colon) and the destination side (after the colon). The ref to be pushed is determined by finding a match that matches the source side, and where it is pushed is determined by using the destination side.</p><blockquote><p>·</p><p>It is an error if <em>&lt;src&gt;</em> does not match exactly one of the local refs.</p></blockquote><blockquote><p>·</p><p>If <em>&lt;dst&gt;</em> does not match any remote ref, either</p><blockquote><p>·</p><p>it has to start with &quot;refs/&quot;; &lt;dst&gt; is used as the destination literally in this case.</p></blockquote><blockquote><p>·</p><p>&lt;src&gt; == &lt;dst&gt; and the ref that matched the &lt;src&gt; must not exist in the set of remote refs; the ref matched &lt;src&gt; locally is used as the name of the destination.</p></blockquote></blockquote><p>Without <strong>--force</strong>, the &lt;src&gt; ref is stored at the remote only if &lt;dst&gt; does not exist, or &lt;dst&gt; is a proper subset (i.e. an ancestor) of &lt;src&gt;. This check, known as &quot;fast-forward check&quot;, is performed in order to avoid accidentally overwriting the remote ref and lose other peoples&#39; commits from there.</p><p>With <strong>--force</strong>, the fast-forward check is disabled for all refs.</p><p>Optionally, a &lt;ref&gt; parameter can be prefixed with a plus <em>+</em> sign to disable the fast-forward check only on that ref.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',30))])}const f=s(h,[["render",p]]);export{k as __pageData,f as default};
